def _portal_data(repo: RepositoryModel) -> dict:
    issues = validate(repo)
    return {
        "config": repo.config,
        "metamodel": {
            "name": repo.metamodel.get("name"),
            "version": repo.metamodel.get("version"),
            "standard": repo.metamodel.get("standard"),
        },
        "metrics": metrics(repo, issues),
        "objects": repo.objects,
        "relationships": repo.relationships,
        "views": repo.views,
        "issues": [i.as_dict() for i in issues],
    }


def render_portal(repo: RepositoryModel, output_dir: str | Path) -> Path:
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)
    data = json.dumps(_portal_data(repo), ensure_ascii=False).replace("</", "<\\/")
    title = f"{repo.config.get('name', 'EA-Ops')} · Architecture Portal"
    html = HTML_TEMPLATE.replace("__TITLE__", title).replace("__DATA__", data)
    out = output_dir / "index.html"
    out.write_text(html, encoding="utf-8")
    return out


def render_report(repo: RepositoryModel, output_file: str | Path) -> Path:
    output_file = Path(output_file)
    output_file.parent.mkdir(parents=True, exist_ok=True)
    issues = validate(repo)
    m = metrics(repo, issues)
    by_type = Counter(o.get("type", "Unknown") for o in repo.objects.values())
    processes = [o for o in repo.objects.values() if o.get("type") == "BusinessProcess"]
    data_objects = [o for o in repo.objects.values() if o.get("type") in {"DataObject", "BusinessObject"}]
    applications = [o for o in repo.objects.values() if o.get("type") == "ApplicationComponent"]

    def p(o, key, default="—"):
        return (o.get("properties") or {}).get(key, default)

    lines = [
        f"# {repo.config.get('name', 'EA-Ops')} — Architecture Report", "", "## Executive Summary", "",
        f"- Quality score: **{m['qualityScore']}/100**", f"- Architecture objects: **{m['objects']}**",
        f"- Relationships: **{m['relationships']}**", f"- Business processes: **{len(processes)}**",
        f"- Data / business objects: **{len(data_objects)}**", f"- Applications: **{len(applications)}**",
        f"- Ownership coverage: **{m['ownershipCoverage']}%**", f"- Documentation coverage: **{m['descriptionCoverage']}%**",
        f"- Validation: **{m['errors']} errors**, **{m['warnings']} warnings**", "", "## Process Repository", "",
        "| Process | Owner | Criticality | Lifecycle | Supporting applications | Data used |",
        "|---|---|---|---|---:|---:|",
    ]
    for proc in sorted(processes, key=lambda x: x.get("name", "")):
        support = [r for r in repo.relationships.values() if r.get("type") == "Serving" and r.get("target") == proc.get("id")]
        data_used = [r for r in repo.relationships.values() if r.get("type") == "Access" and r.get("source") == proc.get("id")]
        lines.append(f"| {proc.get('name','')} | {p(proc,'owner')} | {p(proc,'criticality')} | {p(proc,'lifecycle')} | {len(support)} | {len(data_used)} |")
    lines += ["", "## Data & Information Repository", "", "| Information object | Type | Owner | Classification | Process usage |", "|---|---|---|---|---:|"]
    for item in sorted(data_objects, key=lambda x: x.get("name", "")):
        use_count = sum(1 for r in repo.relationships.values() if r.get("type") == "Access" and r.get("target") == item.get("id"))
        lines.append(f"| {item.get('name','')} | {item.get('type','')} | {p(item,'owner')} | {p(item,'classification','unclassified')} | {use_count} |")
    lines += ["", "## Application Portfolio", "", "| Application | Owner | Lifecycle | Tier | Processes supported |", "|---|---|---|---|---:|"]
    for app in sorted(applications, key=lambda x: x.get("name", "")):
        proc_count = sum(1 for r in repo.relationships.values() if r.get("type") == "Serving" and r.get("source") == app.get("id") and repo.objects.get(r.get("target"), {}).get("type") == "BusinessProcess")
        lines.append(f"| {app.get('name','')} | {p(app,'owner')} | {p(app,'lifecycle')} | {p(app,'tier')} | {proc_count} |")
    lines += ["", "## Catalog by Type", "", "| Type | Count |", "|---|---:|"]
    lines += [f"| {t} | {n} |" for t, n in sorted(by_type.items())]
    lines += ["", "## Validation Findings", "", "| Severity | Rule | Object | Finding |", "|---|---|---|---|"]
    lines += [f"| {i.severity} | {i.code} | {i.object_id or '—'} | {i.message} |" for i in issues] if issues else ["| pass | MODEL_VALID | — | No validation findings |"]
    lines += ["", "## Governance Statement", "", "`main` represents the approved architecture. Proposed changes are reviewed as pull requests, validated by EA-Ops, and published as an interactive repository portal.", "", "The HTML portal provides process drill-down diagrams, information-asset views, application and technology context, relationship navigation, global exploration, and governance results from the same source model."]
    output_file.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return output_file
